\set ON_ERROR_STOP on
BEGIN;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE SCHEMA practice_20260928_125242_982175;
SET search_path TO practice_20260928_125242_982175, public;
CREATE TABLE policies (doc_id text PRIMARY KEY,brand text,status text,title text,embedding vector(384));
CREATE TABLE queries (query_id text PRIMARY KEY,embedding vector(384));
CREATE TABLE embedding_settings (model_id text,revision text,dimensions integer);
COMMIT;
\d policies
SELECT doc_id, title, embedding <=> (SELECT embedding FROM queries WHERE query_id = 'CLASS-dev-01') AS cosine_distance FROM policies WHERE brand = 'Alta' AND status = 'current' ORDER BY cosine_distance, doc_id LIMIT 3;
